def main():
    path = sys.argv[1] if len(sys.argv) > 1 else DEFAULT
    raw = open(path, "rb").read().decode("utf-8")  # คง BOM ไว้
    crlf = "\r\n" in raw
    src = raw.replace("\r\n", "\n")
    if MARKER in src:
        print("[SKIP] คืนของที่หายไว้แล้ว (", MARKER, ") -- ไม่ทำซ้ำ"); return
    out = src  # ตรวจ anchor ทีละจุดบนผลลัพธ์สะสม -- ถ้าจุดใด match != 1 abort ก่อน write
    for p in PATCHES:
        c = out.count(p["old"])
        if c != 1:
            print("[ABORT] anchor %s (%s) match %d ครั้ง (ต้อง 1) -- ยังไม่แก้ไฟล์" % (p["id"], p["range"], c)); sys.exit(1)
        out = out.replace(p["old"], p["new"], 1)
        print("[OK]", p["id"], p["range"])
    bk = path + ".bak_restore_lost_v2"
    if os.path.exists(bk):
        n = 2
        while os.path.exists(bk + str(n)): n += 1
        bk = bk + str(n)
    shutil.copy2(path, bk)
    if crlf: out = out.replace("\n", "\r\n")
    open(path, "wb").write(out.encode("utf-8"))
    print("DONE -> backup:", bk)

if __name__ == "__main__":
    main()
